('L', 7),('C', 6),('D', 5),('B', 5),('I', 5),('U', 6);
CREATE TABLE IF NOT EXISTS POCD_Settings (
	Name TEXT NOT NULL,
	Value INTEGER NOT NULL,
	PRIMARY KEY (Name)
);
INSERT OR REPLACE INTO POCD_Settings (Name, Value) VALUES ('MaxSlots', 14);

-- five new player menus (the leader menu is the game's own PlayerLeader)
INSERT INTO Parameters (ParameterId, Name, Description, Domain, Hash, DefaultValue, ConfigurationGroup, ConfigurationId, GroupId,
	Visible, ReadOnly, SupportsSinglePlayer, SupportsLANMultiplayer, SupportsInternetMultiplayer, SupportsHotSeat, SupportsPlayByCloud,
	ChangeableAfterGameStart, SortIndex) VALUES
('PocdCiv', 'LOC_POCD_MENU_CIV', 'LOC_POCD_MENU_CIV', 'POCD_Civilizations', 0, 'RANDOM', 'Player', 'POCD_CIV', 'PlayerOptions', 1, 0, 0, 1, 1, 0, 0, 0, 3101),
('PocdDistrict', 'LOC_POCD_MENU_DISTRICT', 'LOC_POCD_MENU_DISTRICT', 'POCD_Districts', 0, 'RANDOM', 'Player', 'POCD_UD', 'PlayerOptions', 1, 0, 0, 1, 1, 0, 0, 0, 3102),
('PocdBuilding', 'LOC_POCD_MENU_BUILDING', 'LOC_POCD_MENU_BUILDING', 'POCD_Buildings', 0, 'RANDOM', 'Player', 'POCD_UB', 'PlayerOptions', 1, 0, 0, 1, 1, 0, 0, 0, 3103),
('PocdImprovement', 'LOC_POCD_MENU_IMPROVEMENT', 'LOC_POCD_MENU_IMPROVEMENT', 'POCD_Improvements', 0, 'RANDOM', 'Player', 'POCD_UI', 'PlayerOptions', 1, 0, 0, 1, 1, 0, 0, 0, 3104),
('PocdUnit', 'LOC_POCD_MENU_UNIT', 'LOC_POCD_MENU_UNIT', 'POCD_Units', 0, 'RANDOM', 'Player', 'POCD_UU', 'PlayerOptions', 1, 0, 0, 1, 1, 0, 0, 0, 3105);

INSERT INTO Queries (QueryId, SQL) VALUES
('POCD_CivValues', 'SELECT ''POCD_Civilizations'' AS Domain, p.CivilizationType AS Value, p.CivilizationName AS Name, p.CivilizationAbilityDescription AS Description, p.CivilizationIcon AS Icon, 100 AS SortIndex FROM Players p JOIN POCD_Index x ON x.Cat = ''C'' AND x.Entity = p.CivilizationType WHERE p.Domain = ''Players:Expansion2_Players'' GROUP BY p.CivilizationType'),
('POCD_ItemValues', 'SELECT CASE x.Cat WHEN ''D'' THEN ''POCD_Districts'' WHEN ''B'' THEN ''POCD_Buildings'' WHEN ''I'' THEN ''POCD_Improvements'' ELSE ''POCD_Units'' END AS Domain, i.Type AS Value, i.Name AS Name, i.Description AS Description, i.Icon AS Icon, 100 AS SortIndex FROM PlayerItems i JOIN POCD_Index x ON x.Cat IN (''D'', ''B'', ''I'', ''U'') AND x.Entity = i.Type WHERE i.Domain = ''Players:Expansion2_Players'' AND x.Entity NOT IN (SELECT ItemType FROM POCD_LeaderMechanics) GROUP BY i.Type');
INSERT INTO DomainValueQueries (QueryId) VALUES ('POCD_CivValues'), ('POCD_ItemValues');

INSERT OR REPLACE INTO DomainValues (Domain, Value, Name, Description, Icon, SortIndex) VALUES
('POCD_Civilizations', 'RANDOM', 'LOC_POCD_RANDOM_CIV', 'LOC_POCD_RANDOM_CIV', 'ICON_CIVILIZATION_UNKNOWN', 1),
('POCD_Districts', 'RANDOM', 'LOC_POCD_RANDOM_DISTRICT', 'LOC_POCD_RANDOM_DISTRICT', 'ICON_CIVILIZATION_UNKNOWN', 1),
('POCD_Buildings', 'RANDOM', 'LOC_POCD_RANDOM_BUILDING', 'LOC_POCD_RANDOM_BUILDING', 'ICON_CIVILIZATION_UNKNOWN', 1),
('POCD_Improvements', 'RANDOM', 'LOC_POCD_RANDOM_IMPROVEMENT', 'LOC_POCD_RANDOM_IMPROVEMENT', 'ICON_CIVILIZATION_UNKNOWN', 1),
('POCD_Units', 'RANDOM', 'LOC_POCD_RANDOM_UNIT', 'LOC_POCD_RANDOM_UNIT', 'ICON_CIVILIZATION_UNKNOWN', 1);

-- civilizations may repeat in the draft (only leaders are unique)
UPDATE Parameters SET DefaultValue = 0 WHERE ParameterId = 'NoDupeCivilizations';

